/** Fixed total duration, independent of click time and previous extensions. */
public static function reservation_total_deadline( $order_id, $hours ) {
	if ( ! in_array( (int) $hours, array( 36, 48, 72 ), true ) ) { return 0; }
	$start = absint( get_post_meta( $order_id, '_tkd_fo_reservation_started_at', true ) );
	if ( ! $start ) {
		$invoice = absint( get_post_meta( $order_id, '_tkd_fo_invoice_id', true ) );
		$date = get_post_field( 'post_date_gmt', $invoice ?: $order_id );
		$start = $date ? strtotime( $date . ' UTC' ) : 0;
	}
	return ( $start > 0 && $start <= time() ) ? $start + ( (int) $hours * HOUR_IN_SECONDS ) : 0;
}

extension_helper:
/** Extend the existing deadline; retry callbacks retain their relative-to-now meaning. */
public static function reservation_extension_deadline( $order_id, $hours, $retry = false ) {
	$now = time();
	if ( $retry ) { return $now + ( $hours * HOUR_IN_SECONDS ); }
	$until = absint( get_post_meta( $order_id, '_tkd_fo_reservation_until', true ) );
	if ( is_callable( array( 'TKD_FO_Order_Lifecycle', 'deadline' ) ) ) {
		$until = max( $until, TKD_FO_Order_Lifecycle::deadline( $order_id ) );
	}
	return max( $now, $until ) + ( $hours * HOUR_IN_SECONDS );
}
